    ----------
    walker_weight :

    min_weight :

    max_num_walkers :


    Returns
    -------

    """
def calc_max_num_clones(
    walker_weight: Any, min_weight: Any, max_num_walkers: Any
) -> object {
    max_n_clones = 0;
    n_splits = 2;
    while (
        ((walker_weight / n_splits) >= min_weight) and (n_splits <= max_num_walkers)
    ) {
        n_splits += 1;
    }
    n_splits -= 1;
    max_n_clones = n_splits - 1;
    return max_n_clones;
}

"""
	creates a list of integers from a string (counterpart to list_as_string(l))
	:param s: string
	:return:
	"""
def int_list_from_string(s: Any) -> object {
    if (s == "None") {
        return None;
    }
    l = [];
    for element in s.split(":") {
        l.append(int(element));
    }
    return l;
}

"""
    :param n: number of steps
    :param steps: number of steps that can be taken
    :return: number of ways to use steps
    """
def num_of_ways_to_climb(n: int, steps: list) -> object {
    if (n < min(steps)) {
        return 0;
    }
    ways = 0;
    for step in steps {
        if (n == step) {
            ways += 1;
        } elif (n > step) {
            ways += num_of_ways_to_climb((n - step), steps);
        }
    }
    return ways;
}

