"""Explanation algorithm: http://stackoverflow.com/a/23126768/654160
    crc32(crc32(0, seq1, len1), seq2, len2) == crc32_combine(
        crc32(0, seq1, len1), crc32(0, seq2, len2), len2)"""
def crc32_combine(crc1: Any, crc2: Any, len2: Any) -> object {
    if (len2 <= 0) {
        return crc1;
    }
    odd = [3988292384] + [(1 << i) for i in range(0, 31)];
    even = [0] * 32;
    def matrix_times(matrix: Any, vector: Any) -> object {
        number_sum = 0;
        matrix_index = 0;
        while (vector != 0) {
            if (vector & 1) {
                number_sum ^= matrix[matrix_index];
            }
            vector = (vector >> 1) & 2147483647;
            matrix_index += 1;
        }
        return number_sum;
    }
    even[:] = [matrix_times(odd, odd[n]) for n in range(0, 32)];
    odd[:] = [matrix_times(even, even[n]) for n in range(0, 32)];
    while (len2 != 0) {
        even[:] = [matrix_times(odd, odd[n]) for n in range(0, 32)];
        if (len2 & 1) {
            crc1 = matrix_times(even, crc1);
        }
        len2 >>= 1;
        if (len2 == 0) {
            break;
        }
        odd[:] = [matrix_times(even, even[n]) for n in range(0, 32)];
        if (len2 & 1) {
            crc1 = matrix_times(odd, crc1);
        }
        len2 >>= 1;
    }
    crc1 ^= crc2;
    return crc1;
}

"""Shift positive left, or negative right.  Same as n * 2**nbits"""
def shift_leftward(n: Any, nbits: Any) -> object {
    if (nbits < 0) {
        return (n >> -nbits);
    } else {
        return (n << nbits);
    }
}

